```js
function factorial(n) {
  if (n < 0) throw new Error("No existe factorial de números negativos");

  let resultado = 1;

  for (let i = 2; i <= n; i++) {
    resultado *= i;
  }

  return resultado;
}

console.log(factorial(5)); // 120
console.log(factorial(0)); // 1
```

Versión recursiva:

```js
function factorial(n) {
  if (n < 0) throw new Error("No existe factorial de números negativos");
  if (n === 0 || n === 1) return 1;

  return n * factorial(n - 1);
}

console.log(factorial(5)); // 120
```

Si querés validar que sea entero:

```js
function factorial(n) {
  if (!Number.isInteger(n)) {
    throw new Error("El número debe ser entero");
  }

  if (n < 0) {
    throw new Error("No existe factorial de números negativos");
  }

  let resultado = 1;

  for (let i = 2; i <= n; i++) {
    resultado *= i;
  }

  return resultado;
}
```

Implementación de **quicksort en JavaScript**:

```js
function quicksort(arr) {
  if (arr.length <= 1) {
    return arr;
  }

  const pivote = arr[arr.length - 1];
  const menores = [];
  const mayores = [];

  for (let i = 0; i < arr.length - 1; i++) {
    if (arr[i] < pivote) {
      menores.push(arr[i]);
    } else {
      mayores.push(arr[i]);
    }
  }

  return [...quicksort(menores), pivote, ...quicksort(mayores)];
}

const numeros = [5, 3, 8, 4, 2, 7, 1, 10];

console.log(quicksort(numeros));
// [1, 2, 3, 4, 5, 7, 8, 10]
```

Versión que no modifica el array original.

Con comparación personalizada:

```js
function quicksort(arr, compare = (a, b) => a - b) {
  if (arr.length <= 1) return arr;

  const pivote = arr[arr.length - 1];
  const menores = [];
  const iguales = [];
  const mayores = [];

  for (const item of arr) {
    const cmp = compare(item, pivote);

    if (cmp < 0) menores.push(item);
    else if (cmp > 0) mayores.push(item);
    else iguales.push(item);
  }

  return [
    ...quicksort(menores, compare),
    ...iguales,
    ...quicksort(mayores, compare)
  ];
}

console.log(quicksort([3, 1, 2, 3, 5, 4]));
// [1, 2, 3, 3, 4, 5]
```

Para ordenar objetos:

```js
const personas = [
  { nombre: "Ana", edad: 30 },
  { nombre: "Luis", edad: 20 },
  { nombre: "Marta", edad: 25 }
];

const ordenadas = quicksort(personas, (a, b) => a.edad - b.edad);

console.log(ordenadas);
```
